import os
from typing import Any, Dict, List, Optional

from google.cloud import documentai_v1 as documentai


def _text_from_anchor(document: Any, anchor: Any) -> str:
    if not anchor or not getattr(anchor, "text_segments", None):
        return ""
    parts = []
    for segment in anchor.text_segments:
        start = int(getattr(segment, "start_index", 0) or 0)
        end = int(getattr(segment, "end_index", 0) or 0)
        parts.append(document.text[start:end])
    return "".join(parts).strip()


def _get_field_text(field: Any) -> str:
    if field is None:
        return ""
    if getattr(field, "text_anchor", None):
        return _text_from_anchor(field._pb.document, field.text_anchor)  # type: ignore[attr-defined]
    if getattr(field, "mention_text", None):
        return field.mention_text
    if getattr(field, "value_type", None) and getattr(field.value_type, "text", None):
        return field.value_type.text
    if getattr(field, "normalized_value", None):
        nv = field.normalized_value
        if getattr(nv, "text", None):
            return nv.text
        if getattr(nv, "date_value", None):
            d = nv.date_value
            return f"{getattr(d, 'year', ''):04d}-{getattr(d, 'month', 0):02d}-{getattr(d, 'day', 0):02d}".strip("-")
        if getattr(nv, "money_value", None):
            mv = nv.money_value
            units = getattr(mv, "units", 0) or 0
            nanos = getattr(mv, "nanos", 0) or 0
            return f"{units + nanos / 1e9:.2f}"
    return str(getattr(field, "content", "") or "").strip()


def extract_invoice_fields(
    invoice_bytes: bytes,
    project_id: Optional[str] = None,
    location: Optional[str] = None,
    processor_id: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Google Cloud Document AI Invoice Parser.

    Environment variables used if arguments are omitted:
      - GOOGLE_CLOUD_PROJECT
      - GOOGLE_CLOUD_LOCATION
      - GOOGLE_CLOUD_PROCESSOR_ID
    """
    project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT")
    location = location or os.getenv("GOOGLE_CLOUD_LOCATION", "us")
    processor_id = processor_id or os.getenv("GOOGLE_CLOUD_PROCESSOR_ID")

    if not project_id or not processor_id:
        raise ValueError("project_id and processor_id are required (or set GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_PROCESSOR_ID).")

    client = documentai.DocumentProcessorServiceClient()
    name = client.processor_path(project_id, location, processor_id)

    raw_document = documentai.RawDocument(content=invoice_bytes, mime_type="application/pdf")
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    entities = getattr(document, "entities", []) or []
    item_lines: List[Dict[str, Any]] = []

    vendor = ""
    date = ""
    total = ""

    for entity in entities:
        etype = (getattr(entity, "type_", "") or "").lower()
        val = _get_field_text(entity)
        if etype in {"supplier_name", "vendor_name", "merchant_name"} and not vendor:
            vendor = val
        elif etype in {"invoice_date", "due_date", "date"} and not date:
            date = val
        elif etype in {"total_amount", "total", "amount_due", "balance"} and not total:
            total = val
        elif etype in {"line_item", "item"}:
            props = getattr(entity, "properties", []) or []
            line = {}
            for prop in props:
                ptype = (getattr(prop, "type_", "") or "").lower()
                pval = _get_field_text(prop)
                if ptype:
                    line[ptype] = pval
            if not line:
                line["value"] = val
            item_lines.append(line)

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": item_lines,
    }
